using System;
using System.Collections;
using UnityEngine;
namespace MassiveArmy.Planetary {
    public sealed partial class SettlementHouseholdValidation {
        IEnumerator ValidateSiteProtection(){
            var local=world.Base;var sim=local.Civilisation;var colony=local.Settlements[0];foreach(var faction in sim.State.factions)faction.autonomous=false;sim.Settings.autoExtendSettlementRoads=false;world.Rig.InputEnabled=false;
            for(int i=0;i<10;i++)world.ChangeSimulationSpeed(1);Check(world.SimulationSpeed==8,"Numpad speed ladder caps at 8x");for(int i=0;i<20;i++)world.ChangeSimulationSpeed(-1);Check(world.SimulationSpeed==.25f,"Speed ladder caps at quarter speed");world.ChangeSimulationSpeed(1);world.ChangeSimulationSpeed(1);Check(world.SimulationSpeed==1,"Speed ladder restores exact 1x");
            Time.captureDeltaTime=BattleSettings.Tick;world.Paused=false;uint slowStart=world.SimulationTicks;for(int frame=0;frame<30;frame++)yield return null;uint normalTicks=world.SimulationTicks-slowStart;
            world.ChangeSimulationSpeed(1);world.ChangeSimulationSpeed(1);world.ChangeSimulationSpeed(1);uint fastStart=world.SimulationTicks;double economyStart=sim.State.time;for(int frame=0;frame<30;frame++)yield return null;
            Check(normalTicks>=25&&world.SimulationTicks-fastStart>=normalTicks*6,"8x speed advances actual GPU army ticks faster than 1x");Check(sim.State.time-economyStart>=6,"8x speed also advances the settlement economy clock");world.Paused=true;Time.captureDeltaTime=0;world.ChangeSimulationSpeed(-1);world.ChangeSimulationSpeed(-1);world.ChangeSimulationSpeed(-1);
            local.Factions[0].wallet.Credit(new ResourceCost{materials=6000,fuel=1000});Check(local.TryConstructInfrastructure("mine",0),"Paid mine establishes a recovery site");var mine=local.Buildings[local.Buildings.Count-1];mine.construction=mine.definition.time;Check(mine.persistentId==0,"Fixture attacks a new structure before its first economy identity tick");
            int defender=world.unitCount;bool spawned=false;for(int i=0;i<32&&!spawned;i++)spawned=world.TrySpawnUnit(0,local.TeamOffset(0,new Vector2(140+i*8,210)),0);Check(spawned,"Actual GPU infantry is available to protect the site");var record=new UnitState[1];world.UnitsForValidation.GetData(record,0,defender,1);record[0].flags|=4;world.UnitsForValidation.SetData(record,0,defender,1);
            local.Damage(mine,1);Check(mine.persistentId!=0&&colony.protectionSites[0].original==mine.persistentId,"Immediate attacks allocate a stable site identity before recording recovery");sim.Advance(1);world.UnitsForValidation.GetData(record,0,defender,1);Check(record[0].group==15&&(record[0].flags&8)!=0,"Damage mobilizes idle friendly infantry through a GPU command event");
            Check(local.TryProtectionTarget(0,out var target)&&CubeSphere.ArcDistance(target,CubeSphere.Decode(mine.position),world.definition.radius)<100,"Defensive goal is the attacked structure rather than HQ");Check(colony.protectionSites.Count==1,"Repeated hits share one site incident");
            local.Damage(mine,(uint)Mathf.CeilToInt(mine.health));var site=colony.protectionSites[0];Check(site.destroyed&&local.Nodes[mine.node].claimedBy<0,"Destroyed mine retains a recovery project and releases its actual node");
            local.TickSiteProtection();Check(site.project==0,"No rebuild is spawned immediately during an attack");for(int wait=0;wait<24;wait++)sim.Advance(1);local.TickSiteProtection();var project=local.Buildings.Find(b=>b.persistentId==site.project&&!b.removed);Check(project!=null&&project.definition.id=="autocannon"&&project.awaitingProjectMaterials,"Recovery plans a supplied defensive turret before rebuilding the extractor: "+site.status+", quiet="+(sim.SimulationTime-site.lastHit));
            float progress=project.construction;local.Tick(1);Check(project.construction==progress,"A project cannot construct from treasury money before materials arrive");
            var home=local.Buildings.Find(b=>b.team==0&&b.definition.id=="civil_warehouse");Check(local.Roads.ConnectToNetwork(project,home,out _),"Recovery project has a real paid local road connection");
            var installation=SettlementLogistics.Find(colony,project.persistentId);double stock=colony.inventory.Get("construction_materials");
            // Isolate one actual cart so automatic civilian errands cannot consume this fixture's dispatch slot.
            foreach(var vehicle in colony.cargoVehicles)vehicle.manualDispatchForValidation=true;
            var cart=new CargoVehicleState{id=sim.State.AllocateId(),warehouse=home.persistentId,manualDispatchForValidation=true};colony.cargoVehicles.Add(cart);
            for(int load=0;load<3;load++){
                double shortage=project.definition.cost.materials-installation.inventory.Get("construction_materials");if(shortage<=.01)break;
                Check(sim.Logistics.StartFreightForValidation(local,cart,home,project,"construction_materials",shortage),"A finite road cargo trip carries project supplies");
                for(int i=0;i<4000&&cart.phase!=CargoVehiclePhase.Idle;i++){local.CargoNavigation.Step(.25f,true);sim.Advance(.25);if(i%100==0)yield return null;}
                Check(cart.phase==CargoVehiclePhase.Idle,"Project cart physically delivers and returns");
            }
            Check(installation.inventory.Get("construction_materials")>=project.definition.cost.materials&&colony.inventory.Get("construction_materials")<stock,"Delivered project stock is removed from warehouse inventory");Check(local.ConsumeProjectMaterials(project)&&!project.awaitingProjectMaterials,"Exact delivered project materials unlock construction once");Check(installation.inventory.Get("construction_materials")<.01,"Project inputs are consumed without duplication");
            project.constructionWorkers=1;local.Tick(1);Check(project.construction>0,"Supplied project progresses with an assigned construction worker");
            // Complete fixtures explicitly to exercise the bounded order: turret, four barricades, then original deposit.
            project.construction=project.definition.time;
            for(int stage=1;stage<=5;stage++){sim.Advance(4);local.TickSiteProtection();project=local.Buildings.Find(b=>b.persistentId==site.project&&!b.removed);Check(project!=null&&site.stage==stage,"Protection staging reaches step "+stage);Check(project.definition.id==(stage<5?"wall":"mine"),"Four perimeter cover modules precede the original extractor");if(stage==5)Check(project.node==mine.node,"Rebuild uses the same finite deposit");foreach(var requirement in local.ProjectMaterials(project))SettlementLogistics.Find(colony,project.persistentId).inventory.Deposit(requirement.resource,requirement.amount);Check(local.ConsumeProjectMaterials(project),"Staged project consumes explicit fixture supplies");project.construction=project.definition.time;}
            sim.Advance(4);local.TickSiteProtection();Check(site.finished&&site.fortifications.Count==5,"Recovery completes after turret, four cover modules and extractor");
            int existingCount=local.Buildings.Count;long recoveryId=site.original;local.Damage(project,(uint)Mathf.CeilToInt(project.health));Check(colony.protectionSites.Count==1&&site.original==recoveryId&&!site.finished&&site.stage==5,"Repeated loss reuses the same recovery plan and surviving fortifications");
            for(int wait=0;wait<24;wait++)sim.Advance(1);local.TickSiteProtection();for(int wait=0;wait<32;wait++)sim.Advance(1);local.TickSiteProtection();project=local.Buildings.Find(b=>b.persistentId==site.project&&!b.removed);Check(project!=null&&project.definition.id=="mine"&&local.Buildings.Count==existingCount+1,"Repeated recovery adds only the replacement building, without extra turrets or walls");foreach(var requirement in local.ProjectMaterials(project))SettlementLogistics.Find(colony,project.persistentId).inventory.Deposit(requirement.resource,requirement.amount);Check(local.ConsumeProjectMaterials(project),"Repeated recovery still requires new materials");project.construction=project.definition.time;for(int wait=0;wait<4;wait++)sim.Advance(1);local.TickSiteProtection();Check(site.finished,"Repeated supplied recovery completes");
            int count=colony.protectionSites.Count;local.Sell(project);Check(colony.protectionSites.Count==count&&!colony.protectionSites.Exists(s=>!s.cancelled&&!s.finished&&s.original==project.persistentId),"Selling a building does not create a free reconstruction incident");
            var saved=CivilisationRuntime.Deserialize(sim.Serialize(),sim.State.galaxySeed,sim.Catalogue);Check(saved.colonies[0].protectionSites.Count==colony.protectionSites.Count,"Strategic save retains recovery intent");Check(report.runtimeErrors==0,"Site response, project deliveries and speed controls produce no runtime errors");
        }
    }
}
